package vn.iotstar.config; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import vn.iotstar.entity.Category; import vn.iotstar.entity.Product; import vn.iotstar.entity.Role; import vn.iotstar.entity.User; import vn.iotstar.repository.*;
@Configuration @RequiredArgsConstructor public class DataInitializer{@Bean CommandLineRunner init(RoleRepository roles,UserRepository users,CategoryRepository cats,ProductRepository products,PasswordEncoder enc,@Value("${ADMIN_USERNAME:admin}")String un,@Value("${ADMIN_EMAIL:admin@example.com}")String email,@Value("${ADMIN_PASSWORD:ChangeMe123!}")String pass){return a->{var admin=roles.findByName("ROLE_ADMIN").orElseGet(()->roles.save(new Role("ROLE_ADMIN")));roles.findByName("ROLE_USER").orElseGet(()->roles.save(new Role("ROLE_USER")));if(users.findByUsername(un).isEmpty()){var u=new User();u.setUsername(un);u.setEmail(email);u.setFullName("System Administrator");u.setPassword(enc.encode(pass));u.setRole(admin);u.setEnabled(true);users.save(u);}cats.findByNameIgnoreCase("Mặc định").orElseGet(()->cats.save(new Category("Mặc định")));};}}
